create extension if not exists pgcrypto;
create table if not exists public.products (id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,team text not null,category text not null check(category in ('club','national','special')),description text not null default '',price_cents integer not null check(price_cents>0),image_url text,colors jsonb not null default '[]'::jsonb,sizes text[] not null default array['S','M','L','XL','XXL'],stock integer not null default 0 check(stock>=0),active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'customer' check(role in ('customer','admin')),created_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),status text not null default 'pending' check(status in ('pending','paid','processing','shipped','completed','cancelled','refunded')),currency text not null default 'usd',subtotal_cents integer not null,shipping_cents integer not null default 0,total_cents integer not null,customer_name text not null,customer_email text not null,shipping_address jsonb not null,payment_provider text,payment_session_id text unique,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,size text not null,quantity integer not null check(quantity>0),unit_price_cents integer not null);
create index if not exists products_active_category on public.products(active,category);create index if not exists orders_user_created on public.orders(user_id,created_at desc);
alter table public.products enable row level security;alter table public.profiles enable row level security;alter table public.orders enable row level security;alter table public.order_items enable row level security;
drop policy if exists "Public active products" on public.products;create policy "Public active products" on public.products for select to anon,authenticated using(active=true);
drop policy if exists "Own profile read" on public.profiles;create policy "Own profile read" on public.profiles for select to authenticated using((select auth.uid())=id);
drop policy if exists "Own profile update" on public.profiles;create policy "Own profile update" on public.profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
drop policy if exists "Own orders read" on public.orders;create policy "Own orders read" on public.orders for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Own order items read" on public.order_items;create policy "Own order items read" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())));
drop policy if exists "Admin products manage" on public.products;create policy "Admin products manage" on public.products for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists "Admin orders manage" on public.orders;create policy "Admin orders manage" on public.orders for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
drop policy if exists "Admin items manage" on public.order_items;create policy "Admin items manage" on public.order_items for all to authenticated using((auth.jwt()->'app_metadata'->>'role')='admin') with check((auth.jwt()->'app_metadata'->>'role')='admin');
grant select on public.products to anon,authenticated;grant select,update on public.profiles to authenticated;grant select on public.orders,public.order_items to authenticated;grant all on public.products,public.orders,public.order_items to authenticated;
